const express = require('express');
const pinataSDK = require('@pinata/sdk');
const db = require('../db');

const pinata = new pinataSDK(process.env.PINATA_API_KEY, process.env.PINATA_SECRET_API_KEY);
const app = express();
app.use(express.json());

app.delete('/api/storage/ipfs/:cid', async (req, res) => {
  const { cid } = req.params;

  if (!cid) {
    return res.status(400).json({ error: 'Missing CID parameter' });
  }

  // Verify that the CID was pinned by the authenticated user's organization
  const pinRecord = await db('ipfs_pins')
    .where({ cid: cid, organization_id: req.user.organizationId })
    .first();

  if (!pinRecord) {
    return res.status(404).json({ error: 'Pin record not found or access denied' });
  }

  try {
    await pinata.unpin(cid);
    await db('ipfs_pins').where({ id: pinRecord.id }).delete();
    return res.json({ status: 'success', message: `Unpinned ${cid}` });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

module.exports = app;
